// ── sensitivity grid ──────────────────────────────────────────────────────────

export const grid_center_matches_base = testCell({
  kind: "specification",
  subject: "model.sensitivity",
  inputs: { expected: "fixtures.expected_values" },
  expect: ({ result, inputs }) => {
    const center = result.find((r) => r.exit_multiple === 8.0 && r.tlb_turns === 5.0);
    if (center === undefined) return { pass: false, message: "grid is missing the (8.0x, 5.0x) center" };
    return checkAll([expectClose(center.irr, inputs.expected[0].irr, { abs: 1e-9 })]);
  },
});

export const grid_monotone = testCell({
  kind: "property",
  subject: "model.sensitivity",
  expect: ({ result }) => {
    const byKey = new Map(result.map((r) => [`${r.exit_multiple}|${r.tlb_turns}`, r]));
    const mults = [7.0, 7.5, 8.0, 8.5, 9.0];
    const levs = [4.0, 4.5, 5.0, 5.5, 6.0];
    for (const lev of levs) {
      for (let i = 1; i < mults.length; i += 1) {
        const a = byKey.get(`${mults[i - 1]}|${lev}`);
        const b = byKey.get(`${mults[i]}|${lev}`);
        if (!(b.irr > a.irr)) return { pass: false, message: `IRR not increasing in exit multiple at leverage ${lev}x` };
      }
    }
    for (const m of mults) {
      for (let j = 1; j < levs.length; j += 1) {
        const a = byKey.get(`${m}|${levs[j - 1]}`);
        const b = byKey.get(`${m}|${levs[j]}`);
        if (!(b.irr > a.irr)) return { pass: false, message: `IRR not increasing in leverage at exit ${m}x` };
        if (!(b.sponsor_equity < a.sponsor_equity)) return { pass: false, message: `equity not decreasing in leverage at exit ${m}x` };
      }
    }
    return { pass: true, message: "IRR increases in exit multiple and in leverage; the equity cheque shrinks with leverage (25 re-runs)" };
  },
});

// ── breakeven (goal seek) ─────────────────────────────────────────────────────

export const breakeven_vs_oracle = testCell({
  kind: "specification",
  subject: "model.breakeven_exit_multiple",
  inputs: { expected: "fixtures.expected_values" },
  expect: ({ result, inputs }) => checkAll([
    expectClose(result, inputs.expected[0].breakeven_exit_multiple, { abs: 1e-6 }),
  ]),
});

export const breakeven_implication = testCell({
  kind: "property",
  subject: "model.breakeven_exit_multiple",
  inputs: { expected: "fixtures.expected_values" },
  expect: ({ result, inputs }) => {
    const hurdle = inputs.a[0].hurdle_irr;
    const baseIrr = inputs.expected[0].irr;
    const baseExit = inputs.a[0].exit_multiple;
    if (baseIrr >= hurdle && !(result <= baseExit)) {
      return { pass: false, message: `base IRR clears the hurdle but breakeven ${result.toFixed(3)}x exceeds the exit multiple ${baseExit}x` };
    }
    if (baseIrr < hurdle && !(result > baseExit)) {
      return { pass: false, message: `base IRR misses the hurdle but breakeven ${result.toFixed(3)}x is at or below the exit multiple` };
    }
    return { pass: true, message: "breakeven sits on the correct side of the base exit multiple given IRR vs hurdle" };
  },
});
